8	// ── PetGender JSON converter ──────────────────────────────────────────────────
9	// build.yaml sets field_rename: snake globally, so all camelCase fields are
10	// mapped to snake_case automatically — no @JsonKey(name:) needed here.
11	
12	class _PetGenderConverter implements JsonConverter<PetGender, String?> {
13	  const _PetGenderConverter();
14	
15	  @override
16	  PetGender fromJson(String? json) => PetGender.fromDb(json);
17	
18	  @override
19	  String toJson(PetGender object) => object.dbValue;
20	}
21	
22	// ── Pet ───────────────────────────────────────────────────────────────────────
23	
24	@freezed
25	abstract class Pet with _$Pet {
26	  const Pet._();
27	
28	  const factory Pet({
29	    required String id,
30	    required String ownerId,
31	    required String name,
32	    required String species,
33	    String? breed,
34	    String? avatarUrl,
35	    String? bio,
36	    required DateTime createdAt,
37	    DateTime? dateOfBirth,
38	    @_PetGenderConverter() @Default(PetGender.unknown) PetGender gender,
39	    double? weightKg,
40	    String? activityLevel,
41	    @Default(true) bool isPublic,
42	    @Default(0) int displayOrder,
43	    DateTime? archivedAt,
44	    @Default(false) bool isDiscoverable,
45	    String? handle,
46	    String? accentColor,
47	    DateTime? updatedAt,
48	  }) = _Pet;
49	
50	  factory Pet.fromJson(Map<String, dynamic> json) => _$PetFromJson(json);
51	
52	  PetSpecies get speciesEnum => PetSpecies.fromId(species) ?? PetSpecies.dog;
53	
54	  bool get isArchived => archivedAt != null;
55	
56	  int? get ageInYears {
57	    if (dateOfBirth == null) return null;
58	    final now = DateTime.now();
59	    int years = now.year - dateOfBirth!.year;
60	    if (now.month < dateOfBirth!.month ||
61	        (now.month == dateOfBirth!.month && now.day < dateOfBirth!.day)) {
62	      years--;
63	    }
64	    return years < 0 ? 0 : years;
65	  }
66	
67	  String get ageLabel {
68	    final years = ageInYears;
69	    if (years == null) return 'Age unknown';
70	    if (years == 0) {
71	      final months = _monthsSinceBirth;
72	      return months <= 1 ? '1 month' : '$months months';
73	    }
74	    return years == 1 ? '1 year' : '$years years';
75	  }
76	
77	  int get _monthsSinceBirth {
78	    if (dateOfBirth == null) return 0;
79	    final now = DateTime.now();
80	    return (now.year - dateOfBirth!.year) * 12 +
81	        (now.month - dateOfBirth!.month);
82	  }
83	}
