9	class PetRepository {
10	  const PetRepository(this._client);
11	
12	  final SupabaseClient _client;
13	
14	  /// Fetches active (non-archived) pets owned by the currently authenticated user.
15	  ///
16	  /// The `pets` SELECT RLS policy allows `is_public = true` rows as well as
17	  /// owner rows, so we MUST add an explicit [owner_id] filter — otherwise we
18	  /// would receive every public pet in the database, not just the user's own.
19	  ///
20	  /// Pets are ordered by [display_order] (set via [reorderPets]), then by
21	  /// creation date as a stable tiebreaker.
22	  Future<List<Pet>> fetchPets({bool includeArchived = false}) async {
23	    final userId = _client.auth.currentUser?.id;
24	    if (userId == null) return [];
25	
26	    var query = _client.from('pets').select().eq('owner_id', userId);
27	    if (!includeArchived) {
28	      query = query.filter('archived_at', 'is', null);
29	    }
30	    final rows = await query
31	        .order('display_order', ascending: true)
32	        .order('created_at', ascending: true);
33	    return rows.map(Pet.fromJson).toList();
34	  }
35	
36	  /// Persists a new ordering for the user's pets. Caller passes pet IDs in the
37	  /// order they should appear; the index becomes [display_order].
38	  ///
39	  /// Updates each row individually rather than via a CTE so RLS continues to
40	  /// scope the change to the current user.
41	  Future<void> reorderPets(List<String> orderedPetIds) async {
42	    final userId = _client.auth.currentUser?.id;
43	    if (userId == null) return;
44	    for (var i = 0; i < orderedPetIds.length; i++) {
45	      await _client
46	          .from('pets')
47	          .update({'display_order': i})
48	          .eq('id', orderedPetIds[i])
49	          .eq('owner_id', userId);
50	    }
51	  }
52	
53	  /// Soft-archive a pet. Sets [archived_at] to NOW so the row is filtered out
54	  /// of [fetchPets] but care history is preserved for audit/recovery.
55	  Future<Pet> archivePet(String petId) async {
56	    final row = await _client
57	        .from('pets')
58	        .update({'archived_at': DateTime.now().toUtc().toIso8601String()})
59	        .eq('id', petId)
60	        .select()
61	        .single();
62	    return Pet.fromJson(row);
63	  }
64	
65	  /// Restore a previously-archived pet.
66	  Future<Pet> unarchivePet(String petId) async {
67	    final row = await _client
68	        .from('pets')
69	        .update({'archived_at': null})
70	        .eq('id', petId)
71	        .select()
72	        .single();
73	    return Pet.fromJson(row);
74	  }
75	
76	  Future<Pet> createPet({
77	    required String name,
78	    required String species,
79	    String? breed,
80	    String? avatarUrl,
81	    String? bio,
82	    DateTime? dateOfBirth,
83	    double? weightKg,
84	    String? activityLevel,
85	  }) async {
86	    final userId = _client.auth.currentUser!.id;
87	    final row = await _client.from('pets').insert({
88	      'owner_id': userId,
89	      'name': name,
90	      'species': species,
91	      // ignore: use_null_aware_elements
92	      if (breed != null && !breed.startsWith("Don't")) 'breed': breed,
93	      // ignore: use_null_aware_elements
94	      if (avatarUrl != null) 'avatar_url': avatarUrl,
95	      // ignore: use_null_aware_elements
96	      if (bio != null) 'bio': bio,
97	      // ignore: use_null_aware_elements
98	      if (dateOfBirth != null)
99	        'date_of_birth': dateOfBirth.toIso8601String().split('T').first,
100	      // ignore: use_null_aware_elements
101	      if (weightKg != null) 'weight_kg': weightKg,
102	      // ignore: use_null_aware_elements
103	      if (activityLevel != null) 'activity_level': activityLevel,
104	    }).select().single();
105	    return Pet.fromJson(row);
106	  }
107	
108	  Future<Pet> updateDiscoverable({
109	    required String petId,
110	    required bool discoverable,
111	  }) async {
112	    final row = await _client
113	        .from('pets')
114	        .update({'is_discoverable': discoverable})
115	        .eq('id', petId)
116	        .select()
117	        .single();
118	    return Pet.fromJson(row);
119	  }
120	
121	  Future<Pet> updatePetProfile({
122	    required String id,
123	    required String name,
124	    String? breed,
125	    String? avatarUrl,
126	    String? bio,
127	    DateTime? dateOfBirth,
128	    required PetGender gender,
129	    double? weightKg,
130	    String? activityLevel,
131	    required bool isPublic,
132	  }) async {
133	    final updates = <String, dynamic>{
134	      'name': name.trim(),
135	      'breed': breed?.trim().isEmpty ?? true ? null : breed!.trim(),
136	      'bio': bio?.trim().isEmpty ?? true ? null : bio!.trim(),
137	      'date_of_birth':
138	          dateOfBirth?.toIso8601String().split('T').first,
139	      'gender': gender.dbValue,
140	      'weight_kg': weightKg,
141	      'activity_level':
142	          activityLevel == null || activityLevel.isEmpty ? null : activityLevel,
143	      'is_public': isPublic,
144	    };
145	    if (avatarUrl != null) {
146	      updates['avatar_url'] = avatarUrl;
147	    }
148	
149	    final row =
150	        await _client.from('pets').update(updates).eq('id', id).select().single();
151	    return Pet.fromJson(row);
152	  }
153	
154	  Future<void> writeTargetWeight(String petId, double targetWeightKg) async {
155	    final userId = _client.auth.currentUser!.id;
156	    await _client.from('health_vitals').insert({
157	      'pet_id': petId,
158	      'recorded_by': userId,
159	      'vital_type': 'weight',
160	      'value': targetWeightKg,
161	      'unit': 'kg',
162	      'notes': 'goal',
163	    });
164	  }
165	
166	  Future<void> updateAvatarUrl(String petId, String avatarUrl) async {
167	    await _client
168	        .from('pets')
169	        .update({'avatar_url': avatarUrl})
170	        .eq('id', petId);
171	  }
172	
173	  /// Uploads [bytes] to Supabase Storage under the `pets` bucket and returns
174	  /// the public URL. The `pets` bucket must be created in the Supabase dashboard
175	  /// with public read access enabled.
176	  static const _maxAvatarBytes = 5 * 1024 * 1024;
177	  static const _allowedExtensions = {'jpg', 'jpeg', 'png', 'webp', 'heic', 'heif'};
178	  static const _mimeTypes = {
179	    'jpg': 'image/jpeg',
180	    'jpeg': 'image/jpeg',
181	    'png': 'image/png',
182	    'webp': 'image/webp',
183	    'heic': 'image/heic',
184	    'heif': 'image/heic',
185	  };
186	
187	  Future<String> uploadAvatar(
188	    Uint8List bytes,
189	    String petId, {
190	    String? fileName,
191	  }) async {
192	    if (bytes.isEmpty) {
193	      throw const ValidationException(message: 'Image file is empty.');
194	    }
195	    if (bytes.length > _maxAvatarBytes) {
196	      throw const ValidationException(message: 'Image must be under 5 MB.');
197	    }
198	
199	    final ext = _avatarExtension(fileName);
200	    if (!_allowedExtensions.contains(ext)) {
201	      throw const ValidationException(
202	        message: 'Unsupported image format. Use JPG, PNG, WebP, or HEIC.',
203	      );
204	    }
205	
206	    final path = '$petId/avatar.$ext';
207	    try {
208	      await _client.storage.from('pets').uploadBinary(
209	        path,
210	        bytes,
211	        fileOptions: FileOptions(
212	          contentType: _mimeTypes[ext] ?? 'image/jpeg',
213	          upsert: true,
214	        ),
215	      );
216	    } on StorageException catch (e) {
217	      throw NetworkException(message: 'Photo upload failed: ${e.message}');
218	    }
219	    return _client.storage.from('pets').getPublicUrl(path);
220	  }
221	
222	  static String _avatarExtension(String? fileName) {
223	    if (fileName != null && fileName.contains('.')) {
224	      final ext = fileName.split('.').last.toLowerCase();
225	      if (_allowedExtensions.contains(ext)) return ext == 'jpeg' ? 'jpg' : ext;
226	    }
227	    return 'jpg';
228	  }
229	}
