22	class MatchingRepository {
23	  MatchingRepository(this._ref, this._dataSource);
24	
25	  final Ref _ref;
26	  final MatchingSupabaseDataSource _dataSource;
27	
28	  // Cache only confirmed-true results (location set is stable; "no location" can change).
29	  final Map<String, bool> _petLocationCache = {};
30	
31	  Future<bool> actorPetHasLocation(String petId) async {
32	    if (_petLocationCache[petId] == true) return true;
33	    final hasLoc = await _dataSource.petHasLocation(petId);
34	    if (hasLoc) _petLocationCache[petId] = true;
35	    return hasLoc;
36	  }
37	
38	  void invalidatePetLocationCache(String petId) {
39	    _petLocationCache.remove(petId);
40	  }
41	
42	  /// Syncs the device's current GPS position to the pet's `location` column.
43	  ///
44	  /// Always acquires a fresh fix directly from [LocationService] — bypasses
45	  /// the cached [deviceLatLngProvider] to avoid stale-future and double-timeout
46	  /// issues (the provider's 4 s outer wrapper fires before the GPS's 12 s limit
47	  /// on devices that need more time, particularly emulators).
48	  ///
49	  /// Throws [ValidationException] when location permission is denied or the
50	  /// GPS read fails, and [DatabaseException] on a Supabase write failure.
51	  Future<void> syncActorLocationFromDevice(String activePetId) async {
52	    final coords =
53	        await _ref.read(locationServiceProvider).acquireCurrentLatLng();
54	
55	    try {
56	      await _dataSource.setPetLocationPoint(
57	        petId: activePetId,
58	        latitude: coords.latitude,
59	        longitude: coords.longitude,
60	      );
61	      _petLocationCache[activePetId] = true;
62	    } on PostgrestException catch (e) {
63	      throw DatabaseException.fromPostgrest(e);
64	    }
65	  }
66	
67	  Future<List<MatchingDiscoveryRow>> fetchCandidates({
68	    required String activePetId,
69	    int limit = 20,
70	    DateTime? cursorCreatedAt,
71	    String? cursorPetId,
72	    double radiusMeters = 80467,
73	    List<String>? speciesFilters,
74	    int? minAgeYears,
75	    int? maxAgeYears,
76	  }) async {
77	    final uid = _dataSource.currentUserId;
78	    if (uid == null) return [];
79	
80	    final hasStoredLocation = await actorPetHasLocation(activePetId);
81	    if (!hasStoredLocation) {
82	      unawaited(
83	        syncActorLocationFromDevice(activePetId).catchError((_) {}),
84	      );
85	    }
86	
87	    final species =
88	        (speciesFilters == null || speciesFilters.isEmpty) ? null : speciesFilters;
89	
90	    return _dataSource.fetchDiscoveryCandidates(
91	      actorPetId: activePetId,
92	      radiusMeters: radiusMeters,
93	      limit: limit,
94	      cursorCreatedAt: cursorCreatedAt,
95	      cursorPetId: cursorPetId,
96	      speciesFilters: species,
97	      minAgeYears: minAgeYears,
98	      maxAgeYears: maxAgeYears,
99	    );
100	  }
101	
102	  Future<void> recordSwipe({
103	    required String swiperPetId,
104	    required String swipedPetId,
105	    required String swipedOwnerUserId,
106	    required String action,
107	  }) async {
108	    if (_dataSource.currentUserId == null) return;
109	    if (swipedPetId.startsWith('demo-')) return;
110	
111	    final swipeAction = switch (action) {
112	      'pass' => SwipeTableAction.pass,
113	      'greet' => SwipeTableAction.greet,
114	      'superPaw' => SwipeTableAction.superPaw,
115	      _ => SwipeTableAction.like,
116	    };
117	
118	    try {
119	      await _dataSource.insertSwipe(
120	        actorPetId: swiperPetId,
121	        targetPetId: swipedPetId,
122	        action: swipeAction,
123	      );
124	    } catch (e) {
125	      debugPrint('[MatchingRepository] recordSwipe failed: $e');
126	      rethrow;
127	    }
128	  }
129	
