131	      _dataSource.fetchMatchesForPet(petId);
132	
133	  Future<List<PetSwipe>> fetchSwipesByActor(String actorPetId) =>
134	      _dataSource.fetchSwipesByActor(actorPetId);
135	
136	  Future<Map<String, Map<String, dynamic>>> fetchPetsByIds(
137	          List<String> petIds) =>
138	      _dataSource.fetchPetsByIds(petIds);
139	
140	  Future<void> setActivePetLocation({
141	    required String petId,
142	    required double latitude,
