169	      _dataSource.ensureDirectChatThread(
170	        actorPetId: actorPetId,
171	        otherPetId: otherPetId,
172	      );
173	
174	  Future<List<ChatMessage>> fetchMessages(
175	    String threadId, {
176	    int limit = 50,
177	    DateTime? beforeCreatedAt,
178	  }) =>
179	      _dataSource.fetchMessages(
