9	
10	class MatchingSupabaseDataSource {
11	  MatchingSupabaseDataSource(this._client);
12	
13	  final SupabaseClient _client;
14	
15	  String? get currentUserId => _client.auth.currentUser?.id;
16	
17	  Future<bool> petHasLocation(String petId) async {
18	    final uid = currentUserId;
19	    if (uid == null) return false;
20	
21	    final row = await _client
22	        .from('pets')
23	        .select('id')
24	        .eq('id', petId)
25	        .eq('owner_id', uid)
26	        .not('location', 'is', null)
27	        .maybeSingle();
28	    return row != null;
29	  }
30	
31	  Future<List<MatchingDiscoveryRow>> fetchDiscoveryCandidates({
32	    required String actorPetId,
33	    required double radiusMeters,
34	    int limit = 20,
35	    DateTime? cursorCreatedAt,
36	    String? cursorPetId,
37	    List<String>? speciesFilters,
38	    int? minAgeYears,
39	    int? maxAgeYears,
40	  }) async {
41	    final uid = currentUserId;
42	    if (uid == null) return [];
43	
44	    final List<dynamic> raw;
45	    try {
46	      final response = await _client.rpc(
47	        'matching_discovery_candidates',
48	        params: <String, dynamic>{
49	          'p_actor_pet_id': actorPetId,
50	          'p_radius_meters': radiusMeters,
51	          'p_limit': limit,
52	          'p_cursor_created_at': cursorCreatedAt?.toUtc().toIso8601String(),
53	          'p_cursor_pet_id': cursorPetId,
54	          'p_species': (speciesFilters != null && speciesFilters.isNotEmpty)
55	              ? speciesFilters
56	              : null,
57	          'p_min_age_years': minAgeYears,
58	          'p_max_age_years': maxAgeYears,
59	        },
60	      );
61	      if (response == null) return [];
62	      raw = response as List;
63	    } on PostgrestException catch (e) {
64	      throw DatabaseException.fromPostgrest(e);
65	    }
66	    return raw
67	        .map(
68	          (row) => MatchingDiscoveryRow.fromJson(
69	            Map<String, dynamic>.from(row as Map),
70	          ),
71	        )
72	        .toList(growable: false);
73	  }
74	
75	  Future<void> insertSwipe({
76	    required String actorPetId,
77	    required String targetPetId,
78	    required SwipeTableAction action,
79	  }) async {
80	    await _client.from('swipes').upsert(
81	      {
82	        'actor_id': actorPetId,
83	        'target_id': targetPetId,
84	        'action': action.dbValue,
85	      },
86	      onConflict: 'actor_id,target_id',
87	    );
88	  }
89	
90	  Future<List<PetMutualMatch>> fetchMatchesForPet(String petId) async {
91	    final rows = await _client
92	        .from('matches')
93	        .select()
94	        .or('pet_a_id.eq.$petId,pet_b_id.eq.$petId')
95	        .order('created_at', ascending: false)
96	        .limit(100);
97	
98	    return (rows as List)
99	        .cast<Map<String, dynamic>>()
100	        .map(PetMutualMatch.fromJson)
101	        .toList(growable: false);
102	  }
103	
104	  Future<List<PetSwipe>> fetchSwipesByActor(String actorPetId) async {
105	    final rows = await _client
106	        .from('swipes')
107	        .select()
108	        .eq('actor_id', actorPetId)
109	        .order('created_at', ascending: false);
110	
111	    return (rows as List)
112	        .cast<Map<String, dynamic>>()
113	        .map(PetSwipe.fromJson)
114	        .toList(growable: false);
115	  }
116	
117	  Future<void> setPetLocationPoint({
118	    required String petId,
119	    required double latitude,
