162	  Future<MatchInboxSnapshot> fetchMatchInboxSnapshot(String actorPetId) async {
163	    final uid = currentUserId;
164	    if (uid == null) {
165	      return const MatchInboxSnapshot(newMatches: [], conversations: []);
166	    }
167	
168	    // get_chat_inbox returns both match-based threads and direct message threads.
169	    final raw = await _client.rpc(
170	      'get_chat_inbox',
171	      params: {'p_actor_pet_id': actorPetId},
172	    );
173	    if (raw == null) {
174	      return const MatchInboxSnapshot(newMatches: [], conversations: []);
175	    }
176	
177	    final items = <MatchInboxItem>[];
178	    for (final row in raw as List) {
179	      final map = Map<String, dynamic>.from(row as Map);
180	      final matchedAtRaw = map['matched_at'] as String?;
181	      if (matchedAtRaw == null) continue;
182	      final matchedAt = DateTime.tryParse(matchedAtRaw);
183	      if (matchedAt == null) continue;
184	      final lastAtRaw = map['last_message_at'] as String?;
185	      items.add(
186	        MatchInboxItem(
187	          matchId: map['match_id'] as String?,
188	          threadType: map['thread_type'] as String? ?? 'match',
189	          otherPetId: map['other_pet_id'] as String,
190	          otherPetName: map['other_pet_name'] as String? ?? 'Pet',
191	          otherPetAvatarUrl: map['other_pet_avatar_url'] as String?,
192	          otherPetBreed: map['other_pet_breed'] as String?,
193	          matchedAt: matchedAt,
194	          threadId: map['thread_id'] as String?,
195	          lastMessageAt: lastAtRaw != null ? DateTime.tryParse(lastAtRaw) : null,
196	          lastMessagePreview: map['last_message_preview'] as String?,
197	        ),
198	      );
199	    }
200	
201	    final newMatches = <MatchInboxItem>[];
202	    final conversations = <MatchInboxItem>[];
203	    for (final item in items) {
204	      if (item.isNewMatch) {
205	        newMatches.add(item);
206	      } else {
207	        conversations.add(item);
208	      }
209	    }
210	
211	    newMatches.sort((a, b) => b.matchedAt.compareTo(a.matchedAt));
212	    conversations.sort((a, b) {
213	      final at = a.lastMessageAt ?? a.matchedAt;
214	      final bt = b.lastMessageAt ?? b.matchedAt;
215	      return bt.compareTo(at);
216	    });
217	
218	    return MatchInboxSnapshot(
219	      newMatches: newMatches,
220	      conversations: conversations,
221	    );
222	  }
