254	    int limit = 50,
255	    DateTime? beforeCreatedAt,
256	  }) async {
257	    var builder = _client
258	        .from('chat_messages')
259	        .select()
260	        .eq('thread_id', threadId);
261	
262	    if (beforeCreatedAt != null) {
263	      builder = builder.lt(
264	        'created_at',
265	        beforeCreatedAt.toUtc().toIso8601String(),
266	      );
267	    }
268	
269	    final rows = await builder
270	        .order('created_at', ascending: false)
271	        .limit(limit);
272	
273	    final messages = (rows as List)
274	        .map((row) => ChatMessage.fromJson(Map<String, dynamic>.from(row as Map)))
275	        .toList(growable: false);
276	    return messages.reversed.toList(growable: false);
277	  }
