16	/// Repository for the Social Feed feature.
17	///
18	/// [fetchFeed] returns the public timeline joined with the post's pet
19	/// (avatar / species) and the author user (handle / display name).
20	///
21	/// [toggleLike] **throws** on failure so that
22	/// [SocialNotifier] can catch the error and roll back the optimistic update.
23	class SocialRepository {
24	  SocialRepository(this._client);
25	
26	  final SupabaseClient _client;
27	
28	  String get _uid {
29	    final id = _client.auth.currentUser?.id;
30	    if (id == null) throw const NotAuthenticatedException();
31	    return id;
32	  }
33	
34	  // ── Feed ──────────────────────────────────────────────────────────────────
35	
36	  /// Fetches the public feed.
37	  ///
38	  /// Joins on `pets` for avatar/species/breed and on `users` for the handle.
39	  /// A nested `post_likes` selection lets us compute `isLiked` for the
40	  /// currently active pet without a second round-trip.
41	  Future<List<FeedPost>> fetchFeed({
42	    String? activePetId,
43	    int limit = 15,
44	    int offset = 0,
45	  }) async {
46	    final rows = await _client
47	        .from('posts')
48	        .select('''
49	          id,
50	          content,
51	          image_urls,
52	          created_at,
53	          like_count,
54	          comment_count,
55	          pet:pets!posts_pet_id_fkey!inner(id, name, species, breed, avatar_url),
56	          author:users!posts_author_id_fkey(id, username, display_name, avatar_url, location)
57	        ''')
58	        .eq('visibility', 'public')
59	        .eq('pets.is_public', true)
60	        .order('created_at', ascending: false)
61	        .range(offset, offset + limit - 1);
62	
63	    final posts = (rows as List).cast<Map<String, dynamic>>();
64	
65	    // Fetch only the active pet's likes for this page in a single targeted
66	    // query — replaces the nested post_likes(pet_id) that pulled ALL likes
67	    // for ALL pets on every post.
68	    var likedIds = const <String>{};
69	    if (activePetId != null && posts.isNotEmpty) {
70	      final postIds = posts.map((r) => r['id'] as String).toList();
71	      likedIds = await _fetchLikedPostIds(activePetId, postIds);
72	    }
73	
74	    return posts
75	        .map((r) => _rowToFeedPost(
76	              r,
77	              isLiked: likedIds.contains(r['id'] as String),
78	            ))
79	        .toList(growable: false);
80	  }
