82	  /// Fetches posts authored by a specific pet with offset pagination.
83	  Future<List<FeedPost>> fetchPostsForPet(
84	    String petId, {
85	    String? activePetId,
86	    int limit = 30,
87	    int offset = 0,
88	  }) async {
89	    final rows = await _client
90	        .from('posts')
91	        .select('''
92	          id,
93	          content,
94	          image_urls,
95	          created_at,
96	          like_count,
97	          comment_count,
98	          pet:pets!posts_pet_id_fkey!inner(id, name, species, breed, avatar_url),
99	          author:users!posts_author_id_fkey(id, username, display_name, avatar_url, location)
100	        ''')
101	        .eq('pet_id', petId)
102	        .eq('visibility', 'public')
103	        .eq('pets.is_public', true)
104	        .order('created_at', ascending: false)
105	        .range(offset, offset + limit - 1);
106	
107	    final posts = (rows as List).cast<Map<String, dynamic>>();
108	
109	    var likedIds = const <String>{};
110	    if (activePetId != null && posts.isNotEmpty) {
111	      final postIds = posts.map((r) => r['id'] as String).toList();
112	      likedIds = await _fetchLikedPostIds(activePetId, postIds);
113	    }
114	
115	    return posts
116	        .map((r) => _rowToFeedPost(
117	              r,
118	              isLiked: likedIds.contains(r['id'] as String),
119	            ))
120	        .toList(growable: false);
121	  }
