123	  /// Fetches a single post by its ID.
124	  ///
125	  /// Used when the user navigates directly to `/social/post/:postId` via a
126	  /// deep link or hot-restart, where `state.extra` is null.
127	  Future<FeedPost> fetchPostById({
128	    required String postId,
129	    String? activePetId,
130	  }) async {
131	    final row = await _client
132	        .from('posts')
133	        .select('''
134	          id,
135	          content,
136	          image_urls,
137	          created_at,
138	          like_count,
139	          comment_count,
140	          pet:pets!posts_pet_id_fkey(id, name, species, breed, avatar_url),
141	          author:users!posts_author_id_fkey(id, username, display_name, avatar_url, location)
142	        ''')
143	        .eq('id', postId)
144	        .single();
145	
146	    // Single targeted like-status check (one row, no full-table scan).
147	    final isLiked = activePetId != null
148	        ? await _client
149	              .from('post_likes')
150	              .select('post_id')
151	              .eq('post_id', postId)
152	              .eq('pet_id', activePetId)
153	              .maybeSingle()
154	              .then((r) => r != null)
155	        : false;
156	
157	    return _rowToFeedPost(
158	      Map<String, dynamic>.from(row as Map),
159	      isLiked: isLiked,
160	    );
161	  }
