163	  /// Returns a [FeedPost] from a raw Supabase row.
164	  ///
165	  /// [isLiked] is computed by the caller via a targeted like-status query
166	  /// (either [_fetchLikedPostIds] for list views or a single check for
167	  /// [fetchPostById]) — the nested `post_likes` column is no longer fetched.
168	  FeedPost _rowToFeedPost(Map<String, dynamic> r, {bool isLiked = false}) {
169	    final pet = (r['pet'] as Map?)?.cast<String, dynamic>() ?? const {};
170	    final author = (r['author'] as Map?)?.cast<String, dynamic>() ?? const {};
171	
172	    final petName = (pet['name'] as String?) ?? 'Unknown';
173	    final petSpecies = (pet['species'] as String?) ?? 'dog';
174	    final breed = pet['breed'] as String?;
175	    final handle =
176	        (author['username'] as String?) ??
177	        (author['display_name'] as String?) ??
178	        'petfolio_user';
179	    final fuzzyLocation = (author['location'] as String?) ?? '';
180	
181	    final palette = _paletteFor(petSpecies);
182	
183	    return FeedPost(
184	      id: r['id'] as String,
185	      petId: (pet['id'] as String?) ?? '',
186	      handle: handle,
187	      petName: petName,
188	      petSpecies: petSpecies,
189	      accentColor: palette.accent,
190	      fuzzyLocation: fuzzyLocation,
191	      caption: (r['content'] as String?) ?? '',
192	      likes: (r['like_count'] as int?) ?? 0,
193	      comments: (r['comment_count'] as int?) ?? 0,
194	      timeAgo: r['created_at'] != null
195	          ? formatTimeAgo(DateTime.parse(r['created_at'] as String))
196	          : '',
197	      isLiked: isLiked,
198	      gradientColors: palette.gradient,
199	      subjectColor: palette.subject,
200	      breed: breed,
201	      imageUrls: (r['image_urls'] as List?)?.cast<String>() ?? const [],
202	      petAvatarUrl: pet['avatar_url'] as String?,
203	      videoUrl: r['video_url'] as String?,
204	    );
205	  }
