207	  /// Deterministic colour palette per species so feed cards stay on-brand
208	  /// without needing extra columns in the DB.
209	  _SpeciesPalette _paletteFor(String species) {
210	    switch (species.toLowerCase()) {
211	      case 'cat':
212	        return const _SpeciesPalette(
213	          accent: AppColors.mulberry500,
214	          subject: AppColors.lilac700,
215	          gradient: [AppColors.cream, AppColors.ink300, AppColors.mulberry500],
216	        );
217	      case 'rabbit':
218	        return const _SpeciesPalette(
219	          accent: AppColors.meadow500,
220	          subject: AppColors.mint700,
221	          gradient: [AppColors.mintSoft, AppColors.mint, AppColors.meadow500],
222	        );
223	      case 'dog':
224	      default:
225	        return const _SpeciesPalette(
226	          accent: AppColors.blue500,
