276	  static const _allowedExtensions = {'jpg', 'jpeg', 'png', 'webp', 'gif', 'heic'};
277	  static const _maxImageBytes = 10 * 1024 * 1024; // 10 MB
278	  static const _mimeTypes = {
279	    'jpg':  'image/jpeg',
280	    'jpeg': 'image/jpeg',
281	    'png':  'image/png',
282	    'webp': 'image/webp',
283	    'gif':  'image/gif',
