287	  Future<String> uploadPostImage(XFile file) async {
288	    final ext = file.name.split('.').last.toLowerCase();
289	    if (!_allowedExtensions.contains(ext)) {
290	      throw const ValidationException(message: 'Unsupported image format. Use JPG, PNG, WebP, GIF, or HEIC.');
291	    }
292	
293	    final bytes = await file.readAsBytes();
294	    if (bytes.length > _maxImageBytes) {
295	      throw const ValidationException(message: 'Image must be under 10 MB.');
296	    }
297	
298	    final path = '$_uid/${DateTime.now().millisecondsSinceEpoch}.$ext';
299	    try {
300	      await _client.storage.from('post-images').uploadBinary(
301	        path,
302	        bytes,
303	        fileOptions: FileOptions(contentType: _mimeTypes[ext] ?? 'image/$ext'),
304	      );
305	    } on StorageException catch (e) {
306	      throw NetworkException(message: 'Image upload failed: ${e.message}');
307	    }
308	    return _client.storage.from('post-images').getPublicUrl(path);
309	  }
