97	  static String _loggedDayKey(dynamic v) {
98	    if (v == null) return '';
99	    if (v is String) {
100	      final p = DateTime.tryParse(v);
101	      if (p != null) return _fmtYmd(DateUtils.dateOnly(p.toLocal()));
102	      return v.length >= 10 ? v.substring(0, 10) : v;
103	    }
104	    if (v is DateTime) return _fmtYmd(DateUtils.dateOnly(v.toLocal()));
105	    return '';
106	  }
