116	  static String _taskTypeToLogCareType(CareTaskType t) {
117	    switch (t) {
118	      case CareTaskType.vetVisit:
119	        return 'vet_visit';
120	      case CareTaskType.nailTrim:
121	        return 'nail_trim';
122	      default:
123	        return t.name;
