127	  static String _frequencyToDbString(CareFrequency f) {
128	    switch (f) {
129	      case CareFrequency.twiceDaily:  return 'twice_daily';
130	      case CareFrequency.asNeeded:    return 'as_needed';
131	      default:                        return f.name;
132	    }
133	  }
