135	  static CareTaskType _logCareTypeToTaskType(String careType) {
136	    switch (careType) {
137	      case 'vet_visit':
138	        return CareTaskType.vetVisit;
139	      case 'nail_trim':
140	        return CareTaskType.nailTrim;
141	      default:
142	        for (final v in CareTaskType.values) {
143	          if (v.name == careType) return v;
144	        }
145	        return CareTaskType.other;
146	    }
147	  }
