149	  static String _titleForTaskType(CareTaskType t, String rawCareType) {
150	    switch (t) {
151	      case CareTaskType.feeding:
152	        return 'Feeding';
153	      case CareTaskType.walk:
154	        return 'Walk';
155	      case CareTaskType.grooming:
156	        return 'Grooming';
157	      case CareTaskType.medication:
158	        return 'Medication';
159	      case CareTaskType.vetVisit:
160	        return 'Vet visit';
161	      case CareTaskType.training:
162	        return 'Training';
163	      case CareTaskType.playtime:
164	        return 'Playtime';
165	      case CareTaskType.dental:
166	        return 'Dental';
167	      case CareTaskType.nailTrim:
168	        return 'Nail trim';
169	      case CareTaskType.bath:
170	        return 'Bath';
171	      case CareTaskType.other:
172	        if (rawCareType.isNotEmpty && rawCareType != 'other') {
173	          return rawCareType
174	              .split('_')
175	              .map((s) => s.isEmpty ? s : '${s[0].toUpperCase()}${s.substring(1)}')
176	              .join(' ');
177	        }
178	        return 'Care';
179	    }
180	  }
