182	  static CareTask _careTaskFromLogRow(
183	    Map<String, dynamic> row,
184	    String petId,
185	    DateTime dayLocal,
186	  ) {
187	    final id = row['id'] as String;
188	    final ct = row['care_type'] as String;
189	    final at = row['occurred_at'] as String?;
190	    final t = _logCareTypeToTaskType(ct);
191	    final parsedAt = DateTime.tryParse(at ?? '')?.toLocal() ?? dayLocal;
192	    return CareTask(
193	      id: 'log:$id',
194	      petId: petId,
195	      taskType: t,
196	      title: _titleForTaskType(t, ct),
197	      frequency: CareFrequency.asNeeded,
198	      scheduledTime: null,
199	      isCompleted: true,
200	      completedAt: parsedAt,
201	      gamificationPoints: 0,
202	      notes: null,
203	      categoryIcon: null,
204	      createdAt: dayLocal,
205	      updatedAt: parsedAt,
206	    );
207	  }
