212	  static bool _doneForDay(
213	    CareTask task,
214	    DateTime dayLocal,
215	    bool fromLog,
216	  ) {
217	    if (task.frequency == CareFrequency.once) {
218	      if (fromLog) return true;
219	      if (task.isCompleted &&
220	          task.completedAt != null &&
221	          _localDateOnly(task.completedAt!) == dayLocal) {
222	        return true;
223	      }
224	      return false;
225	    }
226	    return fromLog;
227	  }
