281	  Future<List<CareTask>> bulkCreateTasks(
282	    List<CareTask> tasks, {
283	    bool isAiSuggested = false,
284	  }) async {
285	    try {
286	      if (tasks.isEmpty) return [];
287	      _requireAuth();
288	      final petId = tasks.first.petId;
289	      final existingRows = await _client
290	          .from('care_tasks')
291	          .select('title, task_type, frequency')
292	          .eq('pet_id', petId);
293	
294	      // Both sides normalised to DB snake_case so multi-word types like
295	      // vetVisit/vet_visit and frequencies like twiceDaily/twice_daily match.
296	      final existingTaskSet = existingRows
297	          .map((r) =>
298	              '${r['task_type']}'
299	              '|${r['frequency']}'
300	              '|${(r['title'] as String).toLowerCase().trim()}')
301	          .toSet();
302	
303	      // Today's local date — used to anchor new tasks so they always
304	      // appear on the correct day of week / month regardless of the UTC
305	      // offset between the client and the Supabase server.
306	      final todayLocal = DateUtils.dateOnly(DateTime.now().toLocal());
307	      final todayStr = _fmtYmd(todayLocal);
308	
309	      final payloads = tasks.where((t) {
310	        final key =
311	            '${_taskTypeToLogCareType(t.taskType)}'
312	            '|${_frequencyToDbString(t.frequency)}'
313	            '|${t.title.toLowerCase().trim()}';
314	        return !existingTaskSet.contains(key);
315	      }).map((task) {
316	        final payload = Map<String, dynamic>.from(task.toJson())
317	          ..remove('id')
318	          ..remove('category_icon');
319	        // Always pin anchor_date to today (local). Without this, the DB
320	        // stores NULL and effectiveAnchor falls back to created_at UTC,
321	        // which may differ by a day in positive-offset timezones — causing
322	        // weekly tasks to only appear on the wrong day of the week.
323	        if (payload['anchor_date'] == null) {
324	          payload['anchor_date'] = todayStr;
325	        }
326	        if (isAiSuggested) payload['is_ai_suggested'] = true;
327	        return payload;
328	      }).toList();
329	
330	      if (payloads.isEmpty) return [];
331	
332	      // The DB unique index uses an expression (lower(btrim(title))) which
333	      // cannot be referenced by column name in onConflict. Use ignoreDuplicates
334	      // so Postgres generates ON CONFLICT DO NOTHING against any constraint.
335	      // The client-side pre-filter above is a best-effort optimisation only.
336	      final rows = await _client
337	          .from('care_tasks')
338	          .upsert(payloads, ignoreDuplicates: true)
339	          .select();
340	
341	      final savedTasks = rows.map((row) => CareTask.fromJson(row)).toList();
342	      for (final saved in savedTasks) {
343	        _scheduleNotificationIfNeeded(saved);
344	      }
345	      return savedTasks;
346	    } on AppException {
347	      rethrow;
348	    } on PostgrestException catch (e) {
349	      throw DatabaseException.fromPostgrest(e);
350	    } catch (e) {
351	      throw NetworkException(message: e.toString());
352	    }
353	  }
