406	  /// Fetches all care dashboard data in one `get_care_dashboard_snapshot` RPC
407	  /// call, replacing the previous four parallel round-trips.
408	  Future<CareDashboardSnapshot> fetchDashboardSnapshot({
409	    required String petId,
410	    required DateTime selectedDate,
411	    required List<DateTime> weekDates,
412	  }) async {
413	    try {
414	      _requireAuth();
415	      final dSel = DateUtils.dateOnly(selectedDate);
416	      final dToday = DateUtils.dateOnly(DateTime.now().toLocal());
417	      final weekDays = weekDates.map(DateUtils.dateOnly).toList();
418	      final minD = weekDays.reduce((a, b) => a.isBefore(b) ? a : b);
419	      final maxD = weekDays.reduce((a, b) => a.isAfter(b) ? a : b);
420	
421	      final raw = await _client.rpc(
422	        'get_care_dashboard_snapshot',
423	        params: {
424	          'p_pet_id': petId,
425	          'p_selected_date': _fmtYmd(dSel),
426	          'p_week_start': _fmtYmd(minD),
427	          'p_week_end': _fmtYmd(maxD),
428	          'p_client_today': _fmtYmd(dToday),
429	        },
430	      );
431	
432	      final data = raw as Map<String, dynamic>;
433	
434	      final definitions = (data['tasks'] as List)
435	          .cast<Map<String, dynamic>>()
436	          .map(CareTask.fromJson)
437	          .toList();
438	
439	      final logsSelected =
440	          (data['logs_selected'] as List).cast<Map<String, dynamic>>();
441	      final tasks =
442	          _buildTasksFromSnapshotData(petId, definitions, logsSelected, dSel);
443	
444	      final logsToday =
445	          (data['logs_today'] as List).cast<Map<String, dynamic>>();
446	      final todayTasks = dSel == dToday
447	          ? tasks
448	          : _buildTasksFromSnapshotData(
449	              petId, definitions, logsToday, dToday);
450	
451	      final badgeTypes = (data['badge_types'] as List)
452	          .whereType<String>()
453	          .toSet();
454	
455	      final logsWeek =
456	          (data['logs_week'] as List).cast<Map<String, dynamic>>();
457	      final weekGoalHit = _computeWeekGoalHitFromSnapshotData(
458	        definitions,
459	        logsWeek,
460	        weekDays,
461	      );
462	
463	      return CareDashboardSnapshot(
464	        tasks: tasks,
465	        todayTasks: todayTasks,
466	        badgeTypes: badgeTypes,
467	        weekGoalHit: weekGoalHit,
468	      );
469	    } on AppException {
470	      rethrow;
471	    } on PostgrestException catch (e) {
472	      throw DatabaseException.fromPostgrest(e);
473	    } catch (e) {
474	      throw NetworkException(message: e.toString());
475	    }
476	  }
