478	  /// Builds the per-day task list (applies-on-day + done state) from
479	  /// pre-fetched snapshot data.
480	  List<CareTask> _buildTasksFromSnapshotData(
481	    String petId,
482	    List<CareTask> definitions,
483	    List<Map<String, dynamic>> logs,
484	    DateTime dayLocal,
485	  ) {
486	    // Primary: task_id-based map (new schema — one log entry per real task per day).
487	    // Fallback: care_type-based map for legacy null-task_id entries and
488	    // log-derived synthetic tasks.
489	    final logByTaskId = <String, DateTime?>{};
490	    final logByType = <String, DateTime?>{};
491	
492	    for (final row in logs) {
493	      final taskId = row['task_id'] as String?;
494	      final ct = row['care_type'] as String?;
495	      final raw = row['occurred_at'];
496	      final ts = raw is String ? DateTime.tryParse(raw)?.toLocal() : null;
497	      if (taskId != null) {
498	        logByTaskId.putIfAbsent(taskId, () => ts);
499	      }
500	      if (ct != null) {
501	        logByType.putIfAbsent(ct, () => ts);
502	      }
503	    }
504	
505	    // Count how many applicable tasks share each care_type on this day.
506	    // Used to guard legacy care_type fallback: if multiple tasks share the
507	    // same care_type, one log entry cannot reliably say which task was done.
508	    final taskCountByCareType = <String, int>{};
509	    for (final task in definitions) {
510	      if (!_appliesOnDay(task, dayLocal)) continue;
511	      final ct = _taskTypeToLogCareType(task.taskType);
512	      taskCountByCareType[ct] = (taskCountByCareType[ct] ?? 0) + 1;
513	    }
514	
515	    final out = <CareTask>[];
516	    for (final task in definitions) {
517	      if (!_appliesOnDay(task, dayLocal)) continue;
518	      final careType = _taskTypeToLogCareType(task.taskType);
519	
520	      final bool fromLog;
521	      final DateTime? loggedAt;
522	
523	      if (logByTaskId.containsKey(task.id)) {
524	        // New schema: this task has its own log entry — unambiguous.
525	        fromLog = true;
526	        loggedAt = logByTaskId[task.id];
527	      } else {
528	        // Legacy fallback (null-task_id logs from before the task_id migration).
529	        // Only trust care_type matching when exactly one task of this type
530	        // exists today — otherwise it's ambiguous which task was completed.
531	        final count = taskCountByCareType[careType] ?? 0;
532	        fromLog = count == 1 && logByType.containsKey(careType);
533	        loggedAt = fromLog ? logByType[careType] : null;
534	      }
535	
536	      final done = _doneForDay(task, dayLocal, fromLog);
537	      out.add(task.copyWith(
538	        isCompleted: done,
539	        completedAt: done ? (loggedAt ?? task.completedAt) : null,
540	      ));
541	    }
542	
543	    // Synthesise tasks for log entries with no matching care_task definition
544	    // (ad-hoc entries that have no real task — always null task_id).
545	    final byCareTypeFirstRow = <String, Map<String, dynamic>>{};
546	    for (final row in logs) {
547	      final taskId = row['task_id'] as String?;
548	      if (taskId != null) continue; // skip real-task logs
549	      final ct = row['care_type'] as String?;
550	      if (ct == null) continue;
551	      byCareTypeFirstRow.putIfAbsent(ct, () => row);
552	    }
553	    for (final entry in byCareTypeFirstRow.entries) {
554	      final ct = entry.key;
555	      if (out.any((t) => _taskTypeToLogCareType(t.taskType) == ct)) continue;
556	      out.add(_careTaskFromLogRow(entry.value, petId, dayLocal));
557	    }
558	
559	    out.sort((a, b) {
560	      final la = a.isLogDerived;
561	      final lb = b.isLogDerived;
562	      if (la != lb) return la ? 1 : -1;
563	      return a.title.toLowerCase().compareTo(b.title.toLowerCase());
564	    });
565	    return out;
566	  }
