568	  /// Computes whether each day's expected daily tasks were all completed,
569	  /// from pre-fetched snapshot data.
570	  List<bool> _computeWeekGoalHitFromSnapshotData(
571	    List<CareTask> definitions,
572	    List<Map<String, dynamic>> logsWeek,
573	    List<DateTime> weekDays,
574	  ) {
575	    // Collect all daily tasks grouped by care_type to detect ambiguity.
576	    final dailyTasks = definitions
577	        .where((t) =>
578	            t.frequency == CareFrequency.daily ||
579	            t.frequency == CareFrequency.twiceDaily)
580	        .toList();
581	
582	    if (dailyTasks.isEmpty) {
583	      return List.filled(weekDays.length, true);
584	    }
585	
586	    // Count tasks per care_type to know when legacy care_type fallback is safe.
587	    final dailyCountByCareType = <String, int>{};
588	    for (final task in dailyTasks) {
589	      final ct = _taskTypeToLogCareType(task.taskType);
590	      dailyCountByCareType[ct] = (dailyCountByCareType[ct] ?? 0) + 1;
591	    }
592	
593	    // Build per-day lookup maps (both task_id and care_type).
594	    final byDayTaskIds = <String, Set<String>>{};
595	    final byDayCareTypes = <String, Set<String>>{};
596	    for (final d in weekDays) {
597	      byDayTaskIds[_fmtYmd(d)] = {};
598	      byDayCareTypes[_fmtYmd(d)] = {};
599	    }
600	    for (final row in logsWeek) {
601	      final day = _loggedDayKey(row['logged_date']);
602	      if (day.isEmpty) continue;
603	      final taskId = row['task_id'] as String?;
604	      final ct = row['care_type'] as String?;
605	      if (taskId != null) byDayTaskIds.putIfAbsent(day, () => {}).add(taskId);
606	      if (ct != null) byDayCareTypes.putIfAbsent(day, () => {}).add(ct);
607	    }
608	
609	    return weekDays.map((d) {
610	      final key = _fmtYmd(DateUtils.dateOnly(d));
611	      final completedIds = byDayTaskIds[key] ?? const <String>{};
612	      final completedTypes = byDayCareTypes[key] ?? const <String>{};
613	
614	      return dailyTasks.every((task) {
615	        // Primary: task_id log (new schema — unambiguous).
616	        if (completedIds.contains(task.id)) return true;
617	
618	        // Legacy fallback: care_type log, only when unambiguous (1 task of type).
619	        final ct = _taskTypeToLogCareType(task.taskType);
620	        final count = dailyCountByCareType[ct] ?? 0;
621	        return count == 1 && completedTypes.contains(ct);
622	      });
623	    }).toList();
624	  }
