626	  static void _scheduleNotificationIfNeeded(CareTask task) {
627	    final raw = task.scheduledTime;
628	    if (raw == null || raw.isEmpty) return;
629	    final parts = raw.split(':');
630	    if (parts.length < 2) return;
631	    final hour = int.tryParse(parts[0]);
632	    final minute = int.tryParse(parts[1]);
633	    if (hour == null || minute == null) return;
634	
635	    final tod = TimeOfDay(hour: hour, minute: minute);
636	    final repeating = task.frequency == CareFrequency.daily ||
637	        task.frequency == CareFrequency.twiceDaily;
638	
639	    PlatformNotifications.instance.scheduleTaskReminder(
640	      taskId: task.id,
641	      title: task.title,
642	      tod: tod,
643	      repeating: repeating,
644	    ).ignore();
645	  }
646	
647	  /// Toggles task completion via a single `toggle_care_task` RPC call.
648	  ///
649	  /// [careType] must be the DB snake_case string (e.g. 'vet_visit') and is
650	  /// provided by the caller (already known from the local dashboard state),
651	  /// avoiding an extra round-trip to fetch the task row.
652	  Future<ToggleCompletionResult> toggleCompletion(
653	    String taskId, {
654	    required bool isCompleted,
655	    required String petId,
656	    required String careType,
657	    required DateTime forDay,
658	    required CareTask localTask,
659	  }) async {
660	    try {
661	      _requireAuth();
662	      final now = DateTime.now();
663	      final occurredAt = now.toUtc();
664	      final day = DateUtils.dateOnly(forDay);
665	
666	      final raw = await _client.rpc(
667	        'toggle_care_task',
668	        params: {
669	          'p_task_id':      taskId,
670	          'p_pet_id':       petId,
671	          'p_care_type':    careType,
672	          'p_is_completed': isCompleted,
673	          'p_day':          _fmtYmd(day),
674	          'p_occurred_at':  occurredAt.toIso8601String(),
675	        },
676	      );
677	
678	      if (raw == null) throw const NetworkException(message: 'Empty RPC response');
679	
680	      final result = raw as Map<String, dynamic>;
681	      final badgeUnlocked = result['badge_unlocked'] == true;
682	      final unlockedBadges = (result['unlocked_badges'] as List?)
683	              ?.whereType<String>()
684	              .toList() ??
685	          [];
686	
687	      final rawCompletedAt = result['completed_at'];
688	      final completedAt = rawCompletedAt is String
689	          ? DateTime.tryParse(rawCompletedAt)?.toLocal()
690	          : null;
691	
692	      final merged = localTask.copyWith(
693	        isCompleted: isCompleted,
694	        completedAt: completedAt,
695	        updatedAt: now,
696	      );
697	
698	      return ToggleCompletionResult(
699	        task: merged,
700	        badgeUnlocked: badgeUnlocked,
701	        unlockedBadges: unlockedBadges,
702	      );
703	    } on AppException {
704	      rethrow;
705	    } on PostgrestException catch (e) {
706	      if (e.code == 'PGRST116') throw const NotFoundException();
707	      throw DatabaseException.fromPostgrest(e);
708	    } catch (e) {
709	      throw NetworkException(message: e.toString());
710	    }
711	  }
712	}
