25	  /// Fetch active products with keyset (cursor) pagination.
26	  ///
27	  /// Pass [afterCreatedAt] + [afterId] from the last item of the previous page
28	  /// to get the next page. Omit both for the initial load.
29	  Future<List<Product>> fetchProducts({
30	    DateTime? afterCreatedAt,
31	    String? afterId,
32	    int pageSize = _defaultPageSize,
33	  }) async {
34	    var filterQuery = _client
35	        .from('products')
36	        .select('*, shops!inner(shop_name)')
37	        .eq('active', true)
38	        .gte('inventory_count', 0);
39	
40	    if (afterCreatedAt != null && afterId != null) {
41	      final ts = afterCreatedAt.toUtc().toIso8601String();
42	      filterQuery = filterQuery
43	          .or('created_at.lt.$ts,and(created_at.eq.$ts,id.lt.$afterId)');
44	    }
45	
46	    final rows = await filterQuery
47	        .order('created_at', ascending: false)
48	        .order('id', ascending: false)
49	        .limit(pageSize);
50	
51	    return (rows as List)
52	        .map((r) => Product.fromJson(r as Map<String, dynamic>))
53	        .toList();
