40	  /// Call the Edge Function to create (or retrieve) a Stripe PaymentIntent.
41	  /// Returns the client_secret.
42	  Future<String> createPaymentIntent(String orderId) async {
43	    final response = await _client.functions.invoke(
44	      'create-payment-intent',
45	      body: {'orderId': orderId, 'payment_method': 'stripe'},
46	    );
47	
48	    if (response.status != 200) {
49	      final data = response.data as Map<String, dynamic>?;
50	      final code = data?['code'] as String?;
51	      if (code == 'SHOP_NOT_VERIFIED') throw const ShopNotVerifiedException();
52	      throw Exception('Edge Function error ${response.status}: ${response.data}');
53	    }
54	
55	    final clientSecret =
56	        (response.data as Map<String, dynamic>)['clientSecret'] as String?;
57	    if (clientSecret == null) throw Exception('Missing clientSecret in response');
58	    return clientSecret;
59	  }
