76	
77	    if (response.status != 200) {
78	      final data = response.data as Map<String, dynamic>?;
79	      final code = data?['code'] as String?;
80	      if (code == 'SHOP_NOT_VERIFIED') throw const ShopNotVerifiedException();
81	      throw Exception('Edge Function error ${response.status}: ${response.data}');
82	    }
83	
84	    final checkoutUrl =
85	        (response.data as Map<String, dynamic>)['checkoutUrl'] as String?;
86	    if (checkoutUrl == null) {
87	      throw Exception('Missing checkoutUrl in response');
88	    }
