92	  /// Validate a CoD order via the Edge Function (inventory check, shop active
93	  /// guard) and stamp payment_method='cod' on the row server-side.
94	  /// Returns the confirmed orderId on success.
95	  Future<String> confirmCodOrder(String orderId) async {
96	    final response = await _client.functions.invoke(
97	      'create-payment-intent',
98	      body: {'orderId': orderId, 'payment_method': 'cod'},
99	    );
100	
101	    if (response.status != 200) {
102	      final data = response.data as Map<String, dynamic>?;
103	      final code = data?['code'] as String?;
104	      final message = data?['error'] as String?;
105	      if (code == 'SHOP_INACTIVE') throw const ShopInactiveException();
106	      if (code == 'INSUFFICIENT_STOCK') {
107	        throw InsufficientStockException(
108	          productName: message ?? 'A product',
109	          available: (data?['available'] as num?)?.toInt() ?? 0,
110	          requested: (data?['requested'] as num?)?.toInt() ?? 0,
111	        );
112	      }
113	      throw Exception('CoD confirmation failed ${response.status}: ${response.data}');
114	    }
115	
116	    final data = response.data as Map<String, dynamic>;
117	    return data['orderId'] as String? ?? orderId;
