171	
172	  /// Buyer's full order history, newest first.
173	  Future<List<MarketplaceOrder>> fetchBuyerOrders() async {
174	    final userId = _client.auth.currentUser?.id;
175	    if (userId == null) return [];
176	
177	    final rows = await _client
