188	  /// Vendor's incoming orders for their shop, newest first.
189	  Future<List<MarketplaceOrder>> fetchVendorOrders(String shopId) async {
190	    final rows = await _client
191	        .from('marketplace_orders')
192	        .select()
193	        .eq('shop_id', shopId)
194	        .order('created_at', ascending: false);
195	
196	    return (rows as List)
197	        .map((r) => MarketplaceOrder.fromJson(r as Map<String, dynamic>))
198	        .toList();
