201	  /// Fetch a single order by id.
202	  Future<MarketplaceOrder> fetchOrder(String orderId) async {
203	    final row = await _client
204	        .from('marketplace_orders')
205	        .select()
206	        .eq('id', orderId)
207	        .single();
208	    return MarketplaceOrder.fromJson(row);
