211	  /// Poll until the backend confirms payment (webhook updated the row) or
212	  /// [timeout] elapses.  Throws [PaymentTimeoutException] on timeout so the
213	  /// caller can distinguish "still pending" from a hard failure.
214	  Future<MarketplaceOrder> pollOrderConfirmation(
215	    String orderId, {
216	    Duration timeout = const Duration(seconds: 15),
217	    Duration interval = const Duration(seconds: 2),
218	  }) async {
219	    final deadline = DateTime.now().add(timeout);
220	    while (DateTime.now().isBefore(deadline)) {
221	      final order = await fetchOrder(orderId);
222	      if (order.paymentStatus == PaymentStatus.paid ||
223	          order.status == OrderStatus.processing) {
224	        return order;
225	      }
226	      if (order.status == OrderStatus.cancelled) {
227	        throw Exception('Order was cancelled during verification.');
228	      }
229	      await Future<void>.delayed(interval);
230	    }
231	    throw const PaymentTimeoutException();
232	  }
233	}
