235	/// Stripe confirmed the payment but the backend webhook has not updated the
236	/// order row within the polling window.  The charge almost certainly went
237	/// through — callers should treat this as a soft success and tell the user
238	/// to check their orders.
239	class PaymentTimeoutException implements Exception {
240	  const PaymentTimeoutException();
241	
242	  @override
243	  String toString() =>
244	      'Your payment was accepted but confirmation is still processing. '
245	      'Check your Orders for the final status.';
246	}
