248	class ShopNotVerifiedException implements Exception {
249	  const ShopNotVerifiedException();
250	
251	  @override
252	  String toString() =>
253	      'This seller has not completed their payment setup yet.';
254	}
255	
256	@visibleForTesting
257	Never mapAndThrowCheckoutRpcException(PostgrestException e) {
258	  final msg = e.message;
259	  if (msg.contains('SHOP_INACTIVE')) throw const ShopInactiveException();
260	  if (msg.contains('SHOP_NOT_VERIFIED')) throw const ShopNotVerifiedException();
261	  if (msg.contains('INSUFFICIENT_STOCK:')) {
262	    final parts = msg.split(':');
263	    throw InsufficientStockException(
264	      productName: parts.length > 1 ? parts[1] : 'A product',
265	      available: parts.length > 2 ? int.tryParse(parts[2]) ?? 0 : 0,
266	      requested: parts.length > 3 ? int.tryParse(parts[3]) ?? 0 : 0,
267	    );
268	  }
269	  throw e;
270	}
271	
272	class ShopInactiveException implements Exception {
273	  const ShopInactiveException();
274	
275	  @override
276	  String toString() => 'This shop is currently inactive.';
277	}
278	
279	class InsufficientStockException implements Exception {
280	  const InsufficientStockException({
281	    required this.productName,
282	    required this.available,
283	    required this.requested,
284	  });
285	
286	  final String productName;
287	  final int available;
288	  final int requested;
289	
290	  @override
291	  String toString() =>
292	      'Only $available of "$productName" available (requested $requested).';
293	}
