6	
7	@JsonEnum(fieldRename: FieldRename.snake)
8	enum CareTaskType {
9	  feeding,
10	  walk,
11	  grooming,
12	  medication,
13	  vetVisit,
14	  training,
15	  playtime,
16	  dental,
17	  nailTrim,
18	  bath,
19	  other,
20	}
21	
22	@JsonEnum(fieldRename: FieldRename.snake)
23	enum CareFrequency {
24	  once,
25	  daily,
26	  twiceDaily,
27	  weekly,
28	  biweekly,
29	  monthly,
30	  asNeeded,
31	}
32	
33	@freezed
34	abstract class CareTask with _$CareTask {
35	  const CareTask._();
36	
37	  const factory CareTask({
38	    required String id,
39	    required String petId,
40	    required CareTaskType taskType,
41	    required String title,
42	    required CareFrequency frequency,
43	    String? scheduledTime,
44	    required bool isCompleted,
45	    DateTime? completedAt,
46	    required int gamificationPoints,
47	    String? notes,
48	    String? categoryIcon,
49	    required DateTime createdAt,
50	    required DateTime updatedAt,
51	    // Reference date for recurring tasks (weekly / biweekly / monthly).
52	    // Defaults to createdAt on the server; never null after the first sync.
53	    DateTime? anchorDate,
54	  }) = _CareTask;
55	
56	  factory CareTask.fromJson(Map<String, dynamic> json) =>
57	      _$CareTaskFromJson(json);
58	
59	  String get resolvedCategoryIcon {
60	    final raw = categoryIcon?.trim();
61	    if (raw != null && raw.isNotEmpty) return raw;
62	    return _defaultCategoryIconKey(taskType);
63	  }
64	
65	  IconData get categoryIconData =>
66	      careTaskCategoryIconData(resolvedCategoryIcon, taskType);
67	
68	  /// The effective anchor for recurrence calculations — falls back to createdAt
69	  /// for tasks saved before anchor_date was introduced.
70	  DateTime get effectiveAnchor =>
71	      anchorDate ?? DateUtils.dateOnly(createdAt.toLocal());
72	
73	  /// True when this task applies on today's local date and is not yet done.
74	  bool get isDueToday {
75	    if (isCompleted) return false;
76	    final today = DateUtils.dateOnly(DateTime.now().toLocal());
77	    return appliesToDay(today);
78	  }
79	
80	  /// True when the task was due on any prior day and was not completed.
81	  bool get isOverdue {
82	    if (isCompleted) return false;
83	    if (frequency == CareFrequency.asNeeded) return false;
84	    if (frequency == CareFrequency.once) return false;
85	    // Weekly and biweekly tasks are visible every day within their period window
86	    // (see appliesToDay below). Checking past days would flag them as overdue
87	    // every single day — incorrect. Period-level completion tracking is handled
88	    // via care_logs; the model cannot know about past-window logs here.
89	    if (frequency == CareFrequency.weekly || frequency == CareFrequency.biweekly) {
90	      return false;
91	    }
92	    final today = DateUtils.dateOnly(DateTime.now().toLocal());
93	    final start = DateUtils.dateOnly(effectiveAnchor.toLocal());
94	    // Walk backwards up to 30 days to find a missed daily/monthly occurrence.
95	    for (var i = 1; i <= 30; i++) {
96	      final day = today.subtract(Duration(days: i));
97	      if (day.isBefore(start)) break;
98	      if (appliesToDay(day)) return true;
99	    }
100	    return false;
101	  }
102	
103	  bool appliesToDay(DateTime dayLocal) {
104	    final start = DateUtils.dateOnly(effectiveAnchor.toLocal());
105	    if (dayLocal.isBefore(start)) return false;
106	    switch (frequency) {
107	      case CareFrequency.daily:
108	      case CareFrequency.twiceDaily:
109	      case CareFrequency.asNeeded:
110	        return true;
111	      case CareFrequency.once:
112	        if (isCompleted && completedAt != null) {
113	          return dayLocal == DateUtils.dateOnly(completedAt!.toLocal());
114	        }
115	        return dayLocal == DateUtils.dateOnly(effectiveAnchor.toLocal());
116	      case CareFrequency.weekly:
117	        // Show on ANY day within the current 7-day window from the anchor.
118	        // Previously this was `% 7 == 0` (anchor day-of-week only), which
119	        // made tasks invisible on days other than the exact anchor weekday.
120	        // Users should be able to complete weekly tasks on any convenient day.
121	        return true;
122	      case CareFrequency.biweekly:
123	        // Same rationale as weekly — visible any day in the 14-day window.
124	        return true;
125	      case CareFrequency.monthly:
126	        final lastDay = DateTime(dayLocal.year, dayLocal.month + 1, 0).day;
127	        final anchor = start.day > lastDay ? lastDay : start.day;
128	        return dayLocal.day == anchor;
129	    }
130	  }
131	
132	  bool get isLogDerived => id.startsWith('log:');
133	
134	  CareTask markCompleted() => copyWith(
135	        isCompleted: true,
136	        completedAt: DateTime.now(),
137	        updatedAt: DateTime.now(),
138	      );
139	
140	  CareTask reset() => copyWith(
141	        isCompleted: false,
142	        completedAt: null,
143	        updatedAt: DateTime.now(),
144	      );
145	}
146	
147	IconData careTaskTypeIconData(CareTaskType t) =>
148	    careTaskCategoryIconData(_defaultCategoryIconKey(t), t);
149	
