152	      CareTaskType.walk => 'walk',
153	      CareTaskType.grooming => 'grooming',
154	      CareTaskType.medication => 'medication',
155	      CareTaskType.vetVisit => 'vet_visit',
156	      CareTaskType.training => 'training',
157	      CareTaskType.playtime => 'playtime',
158	      CareTaskType.dental => 'dental',
159	      CareTaskType.nailTrim => 'nail_trim',
160	      CareTaskType.bath => 'bath',
161	      CareTaskType.other => 'other',
162	    };
163	
164	IconData careTaskCategoryIconData(String key, CareTaskType fallbackType) {
165	  switch (key) {
166	    case 'feeding':
167	    case 'restaurant_menu':
168	      return Icons.restaurant_menu_rounded;
169	    case 'walk':
170	    case 'directions_walk':
171	      return Icons.directions_walk_rounded;
172	    case 'grooming':
173	    case 'content_cut':
174	      return Icons.content_cut_rounded;
175	    case 'medication':
176	    case 'medication_liquid':
177	      return Icons.medication_rounded;
178	    case 'vet_visit':
179	    case 'local_hospital':
180	      return Icons.local_hospital_rounded;
181	    case 'training':
182	    case 'school':
183	      return Icons.school_rounded;
184	    case 'playtime':
185	    case 'sports_tennis':
186	      return Icons.sports_tennis_rounded;
187	    case 'dental':
188	    case 'medical_services':
