204	IconData _iconDataForTaskType(CareTaskType t) => switch (t) {
205	      CareTaskType.feeding => Icons.restaurant_menu_rounded,
206	      CareTaskType.walk => Icons.directions_walk_rounded,
207	      CareTaskType.grooming => Icons.content_cut_rounded,
208	      CareTaskType.medication => Icons.medication_rounded,
209	      CareTaskType.vetVisit => Icons.local_hospital_rounded,
