10	class AppointmentRepository {
11	  const AppointmentRepository(this._client);
12	
13	  final SupabaseClient _client;
14	
15	  Future<List<Appointment>> fetchForPet(String petId) async {
16	    try {
17	      final rows = await _client
18	          .from('appointments')
19	          .select()
20	          .eq('pet_id', petId)
21	          .order('scheduled_at', ascending: true);
22	      return (rows as List)
23	          .map((r) => Appointment.fromJson(r as Map<String, dynamic>))
24	          .toList();
25	    } on PostgrestException catch (e) {
26	      throw Exception('Failed to fetch appointments for pet: ${e.message}');
27	    }
28	  }
29	
30	  Future<List<Appointment>> fetchAppointments(String userId, {bool past = false}) async {
31	    try {
32	      final now = DateTime.now().toUtc().toIso8601String();
33	      final PostgrestTransformBuilder<PostgrestList> query;
34	
35	      if (past) {
36	        query = _client
37	            .from('appointments')
38	            .select()
39	            .eq('owner_id', userId)
40	            .lt('scheduled_at', now)
41	            .order('scheduled_at', ascending: false);
42	      } else {
43	        query = _client
44	            .from('appointments')
45	            .select()
46	            .eq('owner_id', userId)
47	            .gte('scheduled_at', now)
48	            .order('scheduled_at', ascending: true);
49	      }
50	
51	      final rows = await query;
52	      return (rows as List)
53	          .map((r) => Appointment.fromJson(r as Map<String, dynamic>))
54	          .toList();
55	    } on PostgrestException catch (e) {
56	      throw Exception('Failed to fetch appointments: ${e.message}');
57	    }
58	  }
59	
60	  Future<Appointment> create(Appointment appointment) async {
61	    final ownerId = _client.auth.currentUser?.id;
62	    if (ownerId == null) {
63	      throw StateError('Must be signed in to create an appointment');
64	    }
65	    try {
66	      final row = await _client
67	          .from('appointments')
68	          .insert(appointment.toInsertJson(ownerId: ownerId))
69	          .select()
70	          .single();
71	      return Appointment.fromJson(Map<String, dynamic>.from(row as Map));
72	    } on PostgrestException catch (e) {
73	      throw Exception('Failed to create appointment: ${e.message}');
74	    }
75	  }
76	
77	  Future<Appointment> updateAppointmentStatus(String appointmentId, String status) async {
78	    try {
79	      final row = await _client
80	          .from('appointments')
81	          .update({'status': status})
82	          .eq('id', appointmentId)
83	          .select()
84	          .single();
85	      return Appointment.fromJson(Map<String, dynamic>.from(row as Map));
86	    } on PostgrestException catch (e) {
87	      throw Exception('Failed to update appointment status: ${e.message}');
88	    }
89	  }
90	
91	  Future<Appointment> rescheduleAppointment(
92	    String appointmentId,
93	    DateTime newDate,
94	    String timeSlot,
95	  ) async {
96	    try {
97	      final rescheduledTime = _combineDateAndTime(newDate, timeSlot);
98	      final row = await _client
99	          .from('appointments')
100	          .update({
101	            'scheduled_at': rescheduledTime.toUtc().toIso8601String(),
102	            'status': 'pending', // Reset to pending when rescheduled
103	          })
104	          .eq('id', appointmentId)
105	          .select()
106	          .single();
107	      return Appointment.fromJson(Map<String, dynamic>.from(row as Map));
108	    } on PostgrestException catch (e) {
109	      throw Exception('Failed to reschedule appointment: ${e.message}');
110	    }
111	  }
112	
113	  Future<void> toggleComplete(String id, {required bool completed}) async {
114	    try {
115	      await _client.from('appointments').update({
116	        'status': completed ? 'completed' : 'pending',
117	      }).eq('id', id);
118	    } on PostgrestException catch (e) {
119	      throw Exception('Failed to toggle completion: ${e.message}');
120	    }
121	  }
122	
123	  Future<void> delete(String id) async {
124	    try {
125	      await _client.from('appointments').delete().eq('id', id);
126	    } on PostgrestException catch (e) {
127	      throw Exception('Failed to delete appointment: ${e.message}');
128	    }
129	  }
130	
131	  DateTime _combineDateAndTime(DateTime date, String timeSlot) {
132	    try {
133	      final cleanSlot = timeSlot.trim().toUpperCase();
134	      final isPm = cleanSlot.contains('PM');
135	      final isAm = cleanSlot.contains('AM');
136	      final timeParts = cleanSlot.replaceAll(RegExp(r'[APM\s]'), '').split(':');
137	      int hour = int.parse(timeParts[0]);
138	      int minute = timeParts.length > 1 ? int.parse(timeParts[1]) : 0;
139	
140	      if (isPm && hour < 12) {
141	        hour += 12;
142	      } else if (isAm && hour == 12) {
143	        hour = 0;
144	      }
145	      return DateTime(date.year, date.month, date.day, hour, minute);
146	    } catch (_) {
147	      return DateTime(date.year, date.month, date.day, date.hour, date.minute);
148	    }
149	  }
150	}
