10	
11	final commentRepositoryProvider = Provider<CommentRepository>(
12	  (ref) => CommentRepository(Supabase.instance.client),
13	);
14	
15	/// Repository for post comments.
16	///
17	/// All methods are thin wrappers around Supabase calls.
18	/// Business logic and state management live in [CommentNotifier].
19	///
20	/// [addComment] and [deleteComment] throw on failure so the controller
21	/// can roll back its optimistic UI update.
22	class CommentRepository {
23	  CommentRepository(this._client);
24	
25	  final SupabaseClient _client;
26	
27	  String get _uid {
28	    final id = _client.auth.currentUser?.id;
29	    if (id == null) throw const NotAuthenticatedException();
30	    return id;
31	  }
32	
33	  // ── Read ─────────────────────────────────────────────────────────────────
34	
35	  /// Fetches all comments for [postId], ordered oldest-first.
36	  ///
37	  /// Joins the `pets` table to get the commenter's handle and name.
38	  Future<List<Comment>> fetchComments({
39	    required String postId,
40	    required String activePetId,
41	  }) async {
42	    final rows = await _client
43	        .from('comments')
44	        .select('id, post_id, pet_id, content, created_at, parent_id, like_count, pet:pets(name, handle, avatar_url)')
45	        .eq('post_id', postId)
46	        .order('created_at', ascending: true);
47	
48	    final comments = (rows as List).cast<Map<String, dynamic>>();
49	
50	    var likedIds = const <String>{};
51	    if (activePetId.isNotEmpty && comments.isNotEmpty) {
52	      final commentIds = comments.map((r) => r['id'] as String).toList();
53	      likedIds = await _fetchLikedCommentIds(activePetId, commentIds);
54	    }
55	
56	    return comments
57	        .map((row) => Comment.fromJson(
58	              row,
59	              activePetId: activePetId,
60	              isLiked: likedIds.contains(row['id'] as String),
61	            ))
62	        .toList();
63	  }
64	
65	  Future<Set<String>> _fetchLikedCommentIds(
66	    String petId,
67	    List<String> commentIds,
68	  ) async {
69	    if (commentIds.isEmpty) return const {};
70	    final rows = await _client
71	        .from('comment_likes')
72	        .select('comment_id')
73	        .eq('pet_id', petId)
74	        .inFilter('comment_id', commentIds);
75	    return {for (final r in (rows as List)) r['comment_id'] as String};
76	  }
77	
78	  // ── Write ────────────────────────────────────────────────────────────────
79	
80	  /// Inserts a new comment. Returns the newly created [Comment].
81	  ///
82	  /// Throws [PostgrestException] on failure.
83	  Future<Comment> addComment({
84	    required String postId,
85	    required String petId,
86	    required String content,
87	    required String activePetId,
88	    String? parentId,
89	  }) async {
90	    final row = await _client
91	        .from('comments')
92	        .insert({
93	          'post_id': postId,
94	          'author_id': _uid,
95	          'pet_id': petId,
96	          'content': content.trim(),
97	          'parent_id': parentId,
98	        })
99	        .select('id, post_id, pet_id, content, created_at, parent_id, like_count, pet:pets(name, handle, avatar_url)')
100	        .single();
101	
102	    return Comment.fromJson(row, activePetId: activePetId);
103	  }
104	
105	  /// Likes or unlikes a comment.
106	  Future<void> toggleCommentLike({
107	    required String commentId,
108	    required String petId,
109	    required bool liked,
110	  }) async {
111	    if (liked) {
112	      await _client.from('comment_likes').upsert({
113	        'comment_id': commentId,
114	        'pet_id': petId,
115	        'user_id': _uid,
116	      }, onConflict: 'comment_id, pet_id');
117	    } else {
118	      await _client
119	          .from('comment_likes')
120	          .delete()
121	          .eq('comment_id', commentId)
122	          .eq('pet_id', petId);
123	    }
124	  }
125	
126	  /// Deletes a comment by [commentId].
127	  ///
128	  /// The RLS policy ensures only the comment's author can delete it.
129	  Future<void> deleteComment(String commentId) async {
130	    await _client.from('comments').delete().eq('id', commentId);
131	  }
132	
133	  /// Updates the [content] of an existing comment.
134	  ///
135	  /// The RLS policy (`author_id = auth.uid()`) enforces ownership server-side,
136	  /// so no client-side guard is needed.
137	  Future<void> updateComment(String commentId, String newContent) async {
138	    await _client
139	        .from('comments')
140	        .update({'content': newContent.trim()})
141	        .eq('id', commentId);
142	  }
143	}
