166	  /// Calls the `stripe-onboard-vendor` Edge Function (not a Postgres RPC).
167	  /// Returns the Stripe account-link URL to open in the user's browser.
168	  Future<String> startOnboarding(String shopId) async {
169	    try {
170	      final response = await _client.functions.invoke(
171	        'stripe-onboard-vendor',
172	        body: {'shopId': shopId},
173	      );
174	
175	      final data = _functionResponseMap(response.data);
176	      final status = response.status;
177	
178	      if (status >= 400) {
179	        throw StripeOnboardingException(_errorMessageFromPayload(data, status));
180	      }
181	
182	      final url = data['accountLinkUrl'] as String?;
183	      if (url == null || url.isEmpty) {
184	        throw const StripeOnboardingException(
185	          'Stripe onboarding did not return a link. Please try again.',
186	        );
187	      }
188	      return url;
189	    } on FunctionException catch (e) {
190	      throw StripeOnboardingException(
191	        _errorMessageFromPayload(_functionResponseMap(e.details), e.status),
192	      );
193	    }
194	  }
