200	  Map<String, dynamic> _functionResponseMap(Object? data) {
201	    if (data == null) return {};
202	    if (data is Map<String, dynamic>) return data;
203	    if (data is Map) return Map<String, dynamic>.from(data);
204	    return {};
205	  }
206	
207	  String _errorMessageFromPayload(Map<String, dynamic> data, int status) {
208	    final error = data['error'];
209	    if (error is String && error.trim().isNotEmpty) return error;
210	    if (error is Map && error['message'] is String) {
211	      return error['message'] as String;
212	    }
213	    return 'Stripe onboarding failed (HTTP $status). Please try again.';
214	  }
215	}
