103	  // ── Image Upload ──────────────────────────────────────────────────────────
104	  static const _allowedExtensions = {'jpg', 'jpeg', 'png', 'webp', 'gif', 'heic'};
105	  static const _maxImageBytes = 10 * 1024 * 1024; // 10 MB
106	  static const _mimeTypes = {
107	    'jpg':  'image/jpeg',
108	    'jpeg': 'image/jpeg',
109	    'png':  'image/png',
110	    'webp': 'image/webp',
111	    'gif':  'image/gif',
112	    'heic': 'image/heic',
113	  };
114	
115	  /// Uploads an image to the post-images bucket and returns the public URL.
116	  Future<String> uploadStoryImage(XFile file) async {
117	    final ext = file.name.split('.').last.toLowerCase();
118	    if (!_allowedExtensions.contains(ext)) {
119	      throw const ValidationException(message: 'Unsupported image format. Use JPG, PNG, WebP, GIF, or HEIC.');
120	    }
121	
122	    final bytes = await file.readAsBytes();
123	    if (bytes.length > _maxImageBytes) {
124	      throw const ValidationException(message: 'Image must be under 10 MB.');
125	    }
126	
127	    final path = '$_uid/${DateTime.now().millisecondsSinceEpoch}.$ext';
128	    try {
129	      await _client.storage.from('post-images').uploadBinary(
130	        path,
131	        bytes,
132	        fileOptions: FileOptions(contentType: _mimeTypes[ext] ?? 'image/$ext'),
133	      );
134	    } on StorageException catch (e) {
135	      throw NetworkException(message: 'Image upload failed: ${e.message}');
136	    }
137	    return _client.storage.from('post-images').getPublicUrl(path);
138	  }
139	}
