3	/// Immutable model for a pet profile shown in the discovery (Playdates) deck.
4	///
5	/// Populated from the `pets` table joined with `users` (for [ownerUserId] and
6	/// [ownerInitial]) and filtered to exclude the active pet and already-swiped
7	/// profiles.  [_sampleDeck] in [DiscoveryNotifier] is used as a warm fallback
8	/// while the real data loads or when the DB has no qualifying profiles.
9	class DiscoveryCandidate {
10	  const DiscoveryCandidate({
11	    required this.petId,
12	    required this.name,
13	    required this.age,
14	    required this.species,
15	    required this.breed,
16	    required this.distance,
17	    required this.ownerInitial,
18	    required this.verified,
19	    required this.traits,
20	    required this.bio,
21	    required this.playStyle,
22	    required this.energy,
23	    required this.bestWith,
24	    required this.vaccinated,
25	    required this.gradientColors,
26	    required this.subjectColor,
27	    this.avatarUrl,
28	    this.ownerUserId,
29	  });
30	
31	  final String petId;
32	  final String name;
33	
34	  /// Human-readable age string, e.g. "3yr" or "8mo".
35	  final String age;
36	
37	  /// Lowercase species string: "dog" | "cat" | "rabbit" | etc.
38	  final String species;
39	
40	  final String breed;
41	
42	  /// Always a fuzzy bucket — never an address.
43	  /// e.g. "Within 2 miles", "Within 5 miles".
44	  /// Derived deterministically from [petId] so no location data is stored.
45	  final String distance;
46	
47	  /// Single letter initial for the safety chip, e.g. "J".
48	  final String ownerInitial;
49	
50	  /// Whether this profile has been vet-verified.
51	  final bool verified;
52	
53	  final List<String> traits;
54	  final String bio;
55	  final String playStyle;
56	  final String energy;
57	  final String bestWith;
58	  final bool vaccinated;
59	
60	  /// Three colours used for the card's gradient background: [start, mid, end].
61	  final List<Color> gradientColors;
62	
63	  /// Base colour for the pet illustration (body blob + ear tints).
